verus! {

/// Given a month number `m` (1..=12) and the weekday index `d` (1..=7) of the first day of that month,
/// returns the number of weeks that month spans on a standard 7-day calendar grid,
/// accounting for leading empty days before the first day.
/// The month lengths correspond to a fixed non-leap year:
/// Jan=31, Feb=28, Mar=31, Apr=30, May=31, Jun=30, Jul=31, Aug=31, Sep=30, Oct=31, Nov=30, Dec=31.
/// Preconditions:
/// - 1 ≤ m ≤ 12
/// - 1 ≤ d ≤ 7
/// Returns an integer between 4 and 6 inclusive.
spec fn days_in_month(m: i8) -> nat {
    requires(m >= 1 && m <= 12);
    ensures(result == 31 || result == 30 || result == 28);
    match m {
        1 => 31,
        2 => 28,
        3 => 31,
        4 => 30,
        5 => 31,
        6 => 30,
        7 => 31,
        8 => 31,
        9 => 30,
        10 => 31,
        11 => 30,
        12 => 31,
        _ => 0, // impossible due to require
    }
}

fn solve(m: i8, d: i8) -> i8
    requires 1 <= m && m <= 12
    requires 1 <= d && d <= 7
    ensures |res: i8| res >= 4 && res <= 6
{
    let days = days_in_month(m) as i8;

    // Compute weeks = 1 + floor((d-1 + days -1) / 7)
    // which is equivalent to ceil((d -1 + days) / 7)
    let numerator = (d - 1) + days;
    let weeks = if numerator % 7 == 0 {
        numerator / 7
    } else {
        numerator / 7 + 1
    };

    // By problem statement weeks ∈ [4,6], assert this property for verification
    assert!(weeks >= 4 && weeks <= 6);

    weeks
}

}